import json
data = json.load(open('/app/resources/treasury_bulletin_1982_03.json'))

# Search for FFO-3 related content
def find_in_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            find_in_dict(v, path + '.' + str(k) if path else str(k))
    elif isinstance(d, list):
        for i, item in enumerate(d):
            find_in_dict(item, f'{path}[{i}]')

# Look for any key with 'gross' or 'interest' in the name
def search_keys(d, keyword=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if keyword.lower() in str(k).lower():
                print(f'Key: {k}')
            search_keys(v, keyword)
    elif isinstance(d, list):
        for item in d:
            search_keys(item, keyword)

search_keys(data, 'gross')
"
